// Builds the MCP tool reference pages from the inventory generated by the
// Yorishiro server tests (tests/fixtures/mcp-inventory.md in yorishiro-ai/yorishiro).
//
//   pnpm generate:mcp [path-or-url-to-inventory.md]
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { defaultLocale, docsDir, translatedLocales } from "../wiki.config.mjs";
import { parseInventory } from "./lib/mcp-inventory.mjs";
import { labels } from "./lib/mcp-labels.mjs";

const DEFAULT_SOURCE =
  "https://raw.githubusercontent.com/yorishiro-ai/yorishiro/develop/tests/fixtures/mcp-inventory.md";
const source = process.argv.slice(2).find((a) => a !== "--") ?? DEFAULT_SOURCE;
let text;
if (/^https?:/.test(source)) {
  const response = await fetch(source);
  if (!response.ok) throw new Error(`Failed to fetch MCP inventory: HTTP ${response.status}`);
  text = await response.text();
} else {
  text = await readFile(source, "utf8");
}

const { community, enterprise } = parseInventory(text);

const cell = (s) => s.replace(/\|/g, "\\|");

function render(l) {
  const out = [];
  out.push("---", `title: "${l.title}"`, `description: "${l.description}"`, "---", "");
  out.push("{/* Generated by scripts/generate-mcp-reference.mjs. Do not edit by hand. */}", "");
  out.push(l.intro, "");
  out.push(`## ${l.tools}`, "");
  out.push(`| ${l.overview.join(" | ")} |`, "| --- | --- | --- | --- |");
  for (const [i, tools] of [community, enterprise].entries())
    for (const t of tools)
      out.push(
        `| [\`${t.name}\`](#${t.name}) | ${l.editions[i]} | \`${t.scope}\` | ${cell(t.description.split(/(?<=\.)\s/)[0])} |`,
      );
  out.push("");
  const section = (heading, note, tools) => {
    out.push(`## ${heading}`, "");
    if (note) out.push(note, "");
    for (const t of tools) {
      out.push(`### ${t.name}`, "", t.description, "", `${l.scope}: \`${t.scope}\``, "");
      if (t.params.length === 0) {
        out.push(l.noParams, "");
        continue;
      }
      out.push(`| ${l.params.join(" | ")} |`, "| --- | --- | --- | --- |");
      for (const p of t.params)
        out.push(
          `| \`${p.name}\` | ${cell(p.type)} | ${p.required ? l.yes : l.no} | ${cell(p.description)} |`,
        );
      out.push("");
    }
  };
  section(l.community, "", community);
  section(l.enterprise, l.enterpriseNote, enterprise);
  return out.join("\n");
}

const outputLocales = [defaultLocale, ...translatedLocales];
for (const locale of outputLocales) {
  if (!labels[locale]) throw new Error(`Missing MCP reference labels for locale: ${locale}`);
}
for (const locale of outputLocales) {
  const l = labels[locale];
  const dir = locale === defaultLocale ? docsDir : join(docsDir, locale);
  await writeFile(join(dir, "reference", "mcp-tools.mdx"), render(l));
}
console.log(`Generated ${community.length} community and ${enterprise.length} enterprise tools.`);
